<span class="line"><span style="color:#ABB2BF;">        x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> F.</span><span style="color:#61AFEF;">elu</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">self</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">conv2</span><span style="color:#ABB2BF;">(x, edge_index))</span></span>
